from collections import OrderedDict
import time


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._store = OrderedDict()  # key -> (value, expiry)

    def get(self, key):
        if key not in self._store:
            return None
        value, expiry = self._store[key]
        if self._clock() >= expiry:
            return None
        self._store.move_to_end(key)
        return value

    def put(self, key, value):
        if self._capacity <= 0:
            return
        is_new = key not in self._store
        if is_new and len(self._store) >= self._capacity:
            now = self._clock()
            expired = [k for k, (_, e) in self._store.items() if now >= e]
            for k in expired:
                del self._store[k]
            while self._store and len(self._store) >= self._capacity:
                self._store.popitem(last=False)
        self._store[key] = (value, self._clock() + self._ttl)
        self._store.move_to_end(key)

    def __len__(self):
        now = self._clock()
        return sum(1 for _, (_, e) in self._store.items() if now < e)
```

- **OrderedDict** provides O(1) `move_to_end` (MRU promotion on `get`/`put`) and `popitem(last=False)` (LRU eviction), satisfying the amortized O(1) constraint for `get`/`put`.
- **`len` is O(n)** by scanning expiry times; the spec only requires `get`/`put` to be O(1) amortized, and expired entries are only purged lazily during capacity-triggered eviction in `put`.
- **Capacity-0 guard** prevents infinite eviction loops; expired entries are only removed during `put` when a new key would exceed capacity, matching the spec's eviction policy exactly.

