import heapq
from typing import Optional

def shortest_path(n: int, edges: list[tuple[int, int, int]], src: int, dst: int) -> tuple[int | None, list[int]]:
    if src == dst:
        return (0, [src])

    # Build adjacency list
    adj: list[list[tuple[int, int]]] = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    INF = float('inf')
    dist = [INF] * n
    prev: list[int | None] = [None] * n
    dist[src] = 0
    heap: list[tuple[int, int]] = [(0, src)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == dst:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    if dist[dst] == INF:
        return (None, [])

    # Reconstruct path
    path: list[int] = []
    node: int | None = dst
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()

    return (dist[dst], path)
```

- Uses early termination: stops as soon as `dst` is popped from the heap, since its distance is guaranteed final with non-negative weights.
- Lazy deletion approach (skip stale heap entries via `d > dist[u]`) avoids the need for a decrease-key operation.
- Predecessor array enables O(path_length) reconstruction with no extra data structures.

