def _eval_expr_inner(s: str) -> float:
    # Tokenize
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\n\r':
            i += 1
        elif c in '+-*/()':
            tokens.append((c, 0.0))
            i += 1
        elif c.isdigit() or c == '.':
            start = i
            has_dot = False
            while i < n and (s[i].isdigit() or s[i] == '.'):
                if s[i] == '.':
                    if has_dot:
                        raise ValueError("Invalid number")
                    has_dot = True
                i += 1
            num_str = s[start:i]
            if num_str == '.':
                raise ValueError("Invalid number")
            tokens.append(('N', float(num_str)))
        else:
            raise ValueError(f"Unexpected character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    # Recursive descent parser
    pos = 0
    tlen = len(tokens)

    def parse_expr():
        nonlocal pos
        result = parse_term()
        while pos < tlen and tokens[pos][0] in ('+', '-'):
            op = tokens[pos][0]
            pos += 1
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        nonlocal pos
        result = parse_factor()
        while pos < tlen and tokens[pos][0] in ('*', '/'):
            op = tokens[pos][0]
            pos += 1
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    def parse_factor():
        nonlocal pos
        if pos < tlen and tokens[pos][0] in ('+', '-'):
            op = tokens[pos][0]
            pos += 1
            val = parse_factor()
            return -val if op == '-' else val
        return parse_atom()

    def parse_atom():
        nonlocal pos
        if pos >= tlen:
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        if tok[0] == 'N':
            pos += 1
            return tok[1]
        elif tok[0] == '(':
            pos += 1
            result = parse_expr()
            if pos >= tlen or tokens[pos][0] != ')':
                raise ValueError("Missing closing parenthesis")
            pos += 1
            return result
        else:
            raise ValueError("Unexpected token")

    result = parse_expr()
    if pos != tlen:
        raise ValueError("Unexpected token after expression")

    return float(result)
```

- Recursive descent parser with grammar `expr → term → factor → atom` naturally enforces precedence and left-associativity without needing operator-precedence tables.
- Tokenizer rejects invalid numbers (e.g., lone `.`, double dots) and unexpected characters early, raising `ValueError` for all malformed inputs.
- Recursion limit is temporarily raised to safely handle nesting depth up to 200 (≈800 stack frames) without exceeding Python's default limit.

