import heapq
from typing import Optional


def shortest_path(n: int, edges: list[tuple[int, int, int]], src: int, dst: int) -> tuple[Optional[int], list[int]]:
    if src == dst:
        return (0, [src])

    # Build adjacency list
    adj: list[list[tuple[int, int]]] = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm
    INF = float('inf')
    dist = [INF] * n
    prev = [-1] * n
    dist[src] = 0

    # Min-heap: (distance, node)
    heap: list[tuple[int, int]] = [(0, src)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == dst:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    if dist[dst] == INF:
        return (None, [])

    # Reconstruct path
    path: list[int] = []
    node = dst
    while node != -1:
        path.append(node)
        node = prev[node]
    path.reverse()

    return (dist[dst], path)
```

- Uses adjacency list + heapq for O((V + E) log V) Dijkstra, well within time limits for 100k nodes and 300k edges.
- Skips stale heap entries (`d > dist[u]`) to avoid redundant relaxations with parallel edges.
- Path reconstruction via predecessor array; early termination when `dst` is popped from the heap.

