        if c == '(':
            pos += 1
            val = parse_expr()
            skip_ws()
            if pos >= n or s[pos] != ')':
                raise ValueError("Expected ')'")
            pos += 1
        elif c == '.' or c.isdigit():
            val = parse_number()
        else:
            raise ValueError("Unexpected character")
        return -val if neg_count & 1 else val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            skip_ws()
            if pos >= n:
                break
            c = s[pos]
            if c == '*':
                pos += 1
                val = val * parse_factor()
            elif c == '/':
                pos += 1
                right = parse_factor()
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                val = val / right
            else:
                break
        return val

