        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos >= n:
                break
            c = s[pos]
            if c == '+':
                pos += 1
                val = val + parse_term()
            elif c == '-':
                pos += 1
                val = val - parse_term()
            else:
                break
        return val

