import math


def _canonical(value: object) -> object:
    """
    Return a hashable canonical representation of a JSON-like value.

    - Dicts are canonicalized as frozensets of (canonical_key, canonical_value)
      pairs, so key order does not matter.
    - Lists/tuples are canonicalized as tuples, so element order matters.
    - Scalars are type-tagged to avoid conflating values such as True/1,
      1/1.0, or a string "nan" with float("nan").
    """
    if value is None:
        return (None,)

    t = type(value)

    if t is bool:
        return (bool, value)

    if t is int:
        return (int, value)

    if t is float:
        # NaN is not equal to itself, so normalize it for duplicate detection.
        if math.isnan(value):
            return (float, "NaN")
        return (float, value)

    if t is str:
        return (str, value)

    if isinstance(value, dict):
        return (
            dict,
            frozenset(
                (_canonical(k), _canonical(v))
                for k, v in value.items()
            ),
        )

    if isinstance(value, (list, tuple)):
        return (list, tuple(_canonical(v) for v in value))

    # Fallback for unexpected but hashable values.
    return (t.__name__, repr(value))


def unique_records(records: list[dict]) -> list[dict]:
    """
    Remove duplicate dict records while preserving first occurrence order.

    Duplicates are determined by canonicalized content, independent of dict
    key order. The original dict objects are returned, not copies.
    """
    seen: set[object] = set()
    result: list[dict] = []

    for record in records:
        key = _canonical(record)

        if key not in seen:
            seen.add(key)
            result.append(record)

    return result
```

