def eval_expr(s):
    # Tokenize
    tokens = []
    i = 0
    n = len(s)
    expect_operand = True

    while i < n:
        c = s[i]
        if c in ' \t\n\r':
            i += 1
            continue
        if '0' <= c <= '9' or c == '.':
            j = i
            while j < n and ('0' <= s[j] <= '9' or s[j] == '.'):
                j += 1
            tok = s[i:j]
            if tok.count('.') > 1 or tok == '.':
                raise ValueError(f"Invalid number: {tok}")
            tokens.append(float(tok))
            expect_operand = False
            i = j
        elif c == '+' or c == '-':
            tokens.append('u' + c if expect_operand else c)
            if not expect_operand:
                expect_operand = True
            i += 1
        elif c == '*' or c == '/':
            tokens.append(c)
            expect_operand = True
            i += 1
        elif c == '(':
            tokens.append('(')
            expect_operand = True
            i += 1
        elif c == ')':
            tokens.append(')')
            expect_operand = False
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # Shunting-yard → postfix
    output = []
    op_stack = []
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, 'u+': 3, 'u-': 3}

    for token in tokens:
        if type(token) is float:
            output.append(token)
        elif token == '(' :
            op_stack.append('(')
        elif token == ')':
            while op_stack and op_stack[-1] != '(':
                output.append(op_stack.pop())
            if not op_stack:
                raise ValueError("Mismatched parentheses")
            op_stack.pop()
        else:
            # operator (binary or unary)
            p = prec[token]
            while op_stack and op_stack[-1] != '(' and prec[op_stack[-1]] > p:
                output.append(op_stack.pop())
            # for left-associative binary ops, also pop equal precedence
            if token in ('+', '-', '*', '/'):
                while op_stack and op_stack[-1] != '(' and prec[op_stack[-1]] == p:
                    output.append(op_stack.pop())
            op_stack.append(token)

    while op_stack:
        if op_stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(op_stack.pop())

    # Evaluate postfix
    stack = []
    for token in output:
        if type(token) is float:
            stack.append(token)
        elif token == 'u+':
            if not stack:
                raise ValueError("Invalid expression")
            # no-op, value stays
        elif token == 'u-':
            if not stack:
                raise ValueError("Invalid expression")
            stack.append(-stack.pop())
        elif token == '+':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop(); stack.append(stack.pop() + b)
        elif token == '-':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop(); stack.append(stack.pop() - b)
        elif token == '*':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop(); stack.append(stack.pop() * b)
        elif token == '/':
            if len(stack) < 2:
                raise ValueError("Invalid expression")
            b = stack.pop()
            if b == 0.0:
                raise ZeroDivisionError("division by zero")
            stack.append(stack.pop() / b)

    if len(stack) != 1:
        raise ValueError("Invalid expression")
    return float(stack[0])
```

**Design notes:**

- **Shunting-yard algorithm** (Dijkstra) converts infix → postfix iteratively, then a simple stack machine evaluates the postfix. No recursion, so 200-deep nesting is just 200 entries on `op_stack`.
- **Unary detection**: a `+`/`-` is unary if `expect_operand` is true (start of expression, after `(`, or after any operator). It's given precedence 3 (above `*`/`/`) and is right-associative (never pops equal-precedence unary ops, so `--2` stacks correctly).
- **Left associativity** for binary ops: when pushing `+`, we pop all `+`/`-` already on the stack (equal precedence + left-assoc → pop). Same for `*`/`/`.
- **Performance**: three linear passes (tokenize, shunting-yard, evaluate) over the token list. For 200k chars that's ~100k tokens × 3 passes — comfortably under 2 seconds. No recursion, no regex, no `eval`.

