import sys

def eval_expr(s: str) -> float:
    """
    Evaluate an arithmetic expression using a recursive-descent parser.

    Supported grammar:
        expr    := term (('+' | '-') term)*
        term    := factor (('*' | '/') factor)*
        factor  := ('+' | '-')* primary
        primary := number | '(' expr ')'
        number  := digits ['.' digits] | '.' digits
    """
    if not isinstance(s, str):
        raise ValueError("expression must be a string")

    n = len(s)
    i = 0

    # Parentheses depth is bounded by 200 in the constraints, but this gives
    # headroom for slightly deeper inputs without risking a hard crash.
    old_limit = sys.getrecursionlimit()
    if old_limit < 10000:
        sys.setrecursionlimit(10000)

    try:
        def skip_spaces() -> None:
            nonlocal i
            while i < n and s[i].isspace():
                i += 1

        def parse_number() -> float:
            nonlocal i

            start = i
            has_digit = False

            while i < n and '0' <= s[i] <= '9':
                i += 1
                has_digit = True

            if i < n and s[i] == '.':
                i += 1
                while i < n and '0' <= s[i] <= '9':
                    i += 1
                    has_digit = True

            if not has_digit:
                raise ValueError("malformed numeric literal")

            try:
                return float(s[start:i])
            except OverflowError:
                # A syntactically valid literal that is too large for float
                # is treated as infinity, matching ordinary float conversion.
                return float("inf")
            except ValueError:
                raise ValueError("malformed numeric literal") from None

        def parse_factor() -> float:
            nonlocal i

            skip_spaces()

            sign = 1.0
            while i < n:
                c = s[i]
                if c == '+':
                    i += 1
                    skip_spaces()
                elif c == '-':
                    sign = -sign
                    i += 1
                    skip_spaces()
                else:
                    break

            if i < n and s[i] == '(':
                i += 1
                value = parse_expr()
                skip_spaces()
                if i >= n or s[i] != ')':
                    raise ValueError("missing closing parenthesis")
                i += 1
                return sign * value

            if i < n and (s[i] == '.' or '0' <= s[i] <= '9'):
                return sign * parse_number()

            raise ValueError("expected number or parenthesized expression")

        def parse_term() -> float:
            nonlocal i

            value = parse_factor()

            while True:
                skip_spaces()
                if i >= n:
                    break

                c = s[i]
                if c == '*':
                    i += 1
                    value *= parse_factor()
                elif c == '/':
                    i += 1
                    value /= parse_factor()
                else:
                    break

            return value

        def parse_expr() -> float:
            nonlocal i

            value = parse_term()

            while True:
                skip_spaces()
                if i >= n:
                    break

                c = s[i]
                if c == '+':
                    i += 1
                    value += parse_term()
                elif c == '-':
                    i += 1
                    value -= parse_term()
                else:
                    break

            return value

        skip_spaces()
        if i >= n:
            raise ValueError("empty expression")

        result = parse_expr()

        skip_spaces()
        if i != n:
            raise ValueError("unexpected trailing characters")

        return float(result)

    finally:
        sys.setrecursionlimit(old_limit)
