from decimal import Decimal, ROUND_HALF_UP

__all__ = ("invoice_total",)

_CENTS = Decimal("0.01")
_TAX_RATES = {
    "DE": Decimal("1.19"),
    "FR": Decimal("1.20"),
    "GB": Decimal("1.20"),
    "US": Decimal("1.00"),
}


def invoice_total(items, country, code=None) -> float:
    if not isinstance(country, str) or country not in _TAX_RATES:
        raise ValueError("Unknown country")

    if code is not None:
        if not isinstance(code, str) or code not in ("SAVE10", "FLAT5"):
            raise ValueError("Invalid discount code")

    subtotal = Decimal("0")
    for item in items:
        subtotal += Decimal(str(item["price"])) * Decimal(str(item["qty"]))

    if code == "SAVE10":
        subtotal *= Decimal("0.90")
    elif code == "FLAT5":
        subtotal -= Decimal("5.00")
        if subtotal < Decimal("0"):
            subtotal = Decimal("0")

    total = subtotal * _TAX_RATES[country]
    total = total.quantize(_CENTS, rounding=ROUND_HALF_UP)
    return float(total)
