from collections import deque
from threading import Lock


class RateLimiter:
    def __init__(self, max_requests: int = 5, window_seconds: float = 10.0) -> None:
        self._max_requests = max_requests
        self._window_seconds = float(window_seconds)
        self._allowed = {}
        self._lock = Lock()

    def allow(self, user_id: str, now: float) -> bool:
        cutoff = now - self._window_seconds

        with self._lock:
            events = self._allowed.get(user_id)

            if events is None:
                if self._max_requests <= 0:
                    return False
                events = deque()
                self._allowed[user_id] = events

            while events and events[0] <= cutoff:
                events.popleft()

            if len(events) < self._max_requests:
                events.append(now)
                return True

            if not events:
                del self._allowed[user_id]

            return False
```

- Uses one bounded deque per user, storing only allowed timestamps in the current 10-second window.
- Prunes timestamps with `<= now - 10` so the interval is exactly `(now - 10, now]`.
- Adds a lock for safe concurrent API calls while keeping per-user memory bounded.
